//! Static format compliance test vectors.
//!
//! Each constant is a pre-generated key pair and ciphertext blob that proves
//! the decoder can round-trip a specific format version and KEM variant. If
//! the wire format ever changes in a breaking way, these tests will fail
//! immediately rather than only when a user encounters an old file.
//!
//! Regenerate all constants with:
//!   cargo run --example gen_vectors -p pqfile
//! Then update the constants below and commit gen_vectors.rs alongside this
//! file so they stay in sync.
//!
//! Plaintext (hex): 707166696c6520737461746963207465737420766563746f72207631

use pqfile::decrypt::decrypt_stream;

const PLAINTEXT: &[u8] = b"pqfile static test vector v1";

